insert into public.products (
  brand_id, slug, title_zh_hk, title_zh_cn, title_en,
  description_zh_hk, description_zh_cn, description_en,
  price_hkd, stock, image_paths, status, sort
)
select b.id, x.slug, x.title_zh_hk, x.title_zh_cn, x.title_en,
  x.description_zh_hk, x.description_zh_cn, x.description_en,
  x.price_hkd, x.stock, x.image_paths, 'on_sale', x.sort
from jsonb_to_recordset($json$[{"brand_slug":"lanluis","slug":"youthful-bust-enriching-cream","title_zh_hk":"\u9b45\u529b\u5e7c\u808c\u8c50\u76c8\u4e73\u971c","title_zh_cn":"\u9b45\u529b\u5e7c\u808c\u4e30\u76c8\u4e73\u971c","title_en":"Youthful Bust Enriching Cream","description_zh_hk":"<p>\u542b\u6709\u8c50\u5bcc\u7684\u690d\u7269\u63d0\u53d6\u7cbe\u83ef\uff0c\u7279\u6b8a\u6d3b\u8e8d\u6210\u4efd\u52a0\u5f37\u817a\u9ad4\u5faa\u74b0\u53ca\u9810\u9632\u6de4\u585e\uff0c\u5c0d\u5973\u6027\u6709\u7f8e\u80f8\u529f\u6548\uff0c\u5728\u80f8\u90e8\u5468\u570d\u9032\u884c\u908a\u64e6\u62b9\u908a\u6309\u6469\u7684\u65b9\u5f0f\uff0c\u53ef\u4ee5\u4fdd\u990a\u4fee\u8b77\u5973\u6027\u7684\u80f8\u90e8\uff0c\u4f7f\u80f8\u90e8\u8c50\u6eff\uff0c\u66f4\u6709\u9b45\u529b\u3002</p>\n\n<p>\u4e3b\u8981\u6210\u4efd</p>\n<p>\u2013 \u6d3b\u6cc9\u6c34</p>\n<p>\u2013 \u5564\u9152\u82b1\u8403\u53d6\u7269</p>\n<p>\u2013 \u7d05\u82b1\u8403\u53d6\u7269</p>\n<p>\u2013 \u767e\u5408\u8403\u53d6\u7269</p>\n<p>\u2013 \u9178\u68d7\u4ec1\u8403\u53d6\u7269</p>\n<p>\u2013 \u7dad\u751f\u7d20A\u548cD</p>\n\n<p>\u9069\u5408\u4eba\u58eb</p>\n<p>\u2013 \u9069\u7528\u65bc\u7522\u5f8c\u9b06\u5f1b</p>\n<p>\u2013 \u4e73\u623f\u840e\u7e2e</p>\n<p>\u2013 \u6a5f\u80fd\u6e1b\u9000</p>\n<p>\u2013 \u4e73\u623f\u8b8a\u5f62</p>\n<p>\u2013 \u4e0b\u5782</p>","description_zh_cn":"<p>\u542b\u6709\u4e30\u5bcc\u7684\u690d\u7269\u63d0\u53d6\u7cbe\u534e\uff0c\u7279\u6b8a\u6d3b\u8dc3\u6210\u4efd\u52a0\u5f3a\u817a\u4f53\u5faa\u73af\u53ca\u9884\u9632\u6de4\u585e\uff0c\u5bf9\u5973\u6027\u6709\u7f8e\u80f8\u529f\u6548\uff0c\u5728\u80f8\u90e8\u5468\u56f4\u8fdb\u884c\u8fb9\u64e6\u62b9\u8fb9\u6309\u6469\u7684\u65b9\u5f0f\uff0c\u53ef\u4ee5\u4fdd\u517b\u4fee\u62a4\u5973\u6027\u7684\u80f8\u90e8\uff0c\u4f7f\u80f8\u90e8\u4e30\u6ee1\uff0c\u66f4\u6709\u9b45\u529b\u3002</p>\n\n<p>\u4e3b\u8981\u6210\u4efd</p>\n<p>\u2013 \u6d3b\u6cc9\u6c34</p>\n<p>\u2013 \u5564\u9152\u82b1\u8403\u53d6\u7269</p>\n<p>\u2013 \u7ea2\u82b1\u8403\u53d6\u7269</p>\n<p>\u2013 \u767e\u5408\u8403\u53d6\u7269</p>\n<p>\u2013 \u9178\u67a3\u4ec1\u8403\u53d6\u7269</p>\n<p>\u2013 \u7ef4\u751f\u7d20A\u548cD</p>\n\n<p>\u9002\u5408\u4eba\u58eb</p>\n<p>\u2013 \u9002\u7528\u4e8e\u4ea7\u540e\u677e\u5f1b</p>\n<p>\u2013 \u4e73\u623f\u840e\u7f29</p>\n<p>\u2013 \u673a\u80fd\u51cf\u9000</p>\n<p>\u2013 \u4e73\u623f\u53d8\u5f62</p>\n<p>\u2013 \u4e0b\u5782</p>","description_en":"<p>Rich botanical extracts and actives to support glandular circulation and help prevent congestion. Massage around the bust to nourish, plump and enhance contour.</p>\n<p>Key ingredients</p>\n<p>\u2013 Spring water</p>\n<p>\u2013 Hops extract</p>\n<p>\u2013 Safflower extract</p>\n<p>\u2013 Lily extract</p>\n<p>\u2013 Ziziphus seed extract</p>\n<p>\u2013 Vitamins A and D</p>\n<p>Suitable for</p>\n<p>\u2013 Postpartum laxity</p>\n<p>\u2013 Breast atrophy</p>\n<p>\u2013 Reduced function</p>\n<p>\u2013 Shape changes</p>\n<p>\u2013 Sagging</p>","price_hkd":838,"stock":20,"image_paths":["/images/products/prod-18@2x.jpg"],"sort":212}]$json$::jsonb) as x(
  brand_slug text, slug text, title_zh_hk text, title_zh_cn text, title_en text,
